run('prepared_plans',"PREPARE parent_check(text) AS "+q+"; SET LOCAL plan_cache_mode=force_custom_plan; EXPLAIN (VERBOSE,FORMAT JSON) EXECUTE parent_check('tax-2026.10.07-01'); SET LOCAL plan_cache_mode=force_generic_plan; EXPLAIN (ANALYZE,BUFFERS,VERBOSE,SETTINGS,FORMAT JSON) EXECUTE parent_check('tax-2026.09.30-01'); DEALLOCATE parent_check;")
run('retry_safety',"""SELECT jsonb_build_object('time',clock_timestamp(),'active',(SELECT jsonb_agg(release_id) FROM public.taxonomy_v2_releases WHERE status='active'),'concepts',(SELECT count(*) FROM public.taxonomy_v2_concepts),'vernaculars',(SELECT count(*) FROM public.taxonomy_v2_vernacular_names WHERE release_id='tax-2026.09.30-01'),'target_rows',jsonb_build_object('release',(SELECT count(*) FROM public.taxonomy_v2_releases WHERE release_id='tax-2026.10.07-01'),'runs',(SELECT count(*) FROM public.taxonomy_v2_import_runs WHERE release_id='tax-2026.10.07-01'),'taxa',(SELECT count(*) FROM public.taxonomy_v2_taxa WHERE release_id='tax-2026.10.07-01'),'scientific',(SELECT count(*) FROM public.taxonomy_v2_scientific_names WHERE release_id='tax-2026.10.07-01'),'external',(SELECT count(*) FROM public.taxonomy_v2_external_ids WHERE release_id='tax-2026.10.07-01'),'legacy',(SELECT count(*) FROM public.taxonomy_v2_legacy_external_ids WHERE release_id='tax-2026.10.07-01'),'vernacular',(SELECT count(*) FROM public.taxonomy_v2_vernacular_names WHERE release_id='tax-2026.10.07-01'),'redlist',(SELECT count(*) FROM public.taxonomy_v2_redlist WHERE release_id='tax-2026.10.07-01')));
 SELECT jsonb_build_object('function_count_result',public.taxonomy_v2_validate_release('tax-2026.09.30-01'),'timeout',current_setting('statement_timeout'));""")
